#include <bits/stdc++.h>
#define MOD 1000000007LL
#define pb push_back
using namespace std;
using ll = long long;

ll N, K;

class Matrix {
public:
    vector<vector<ll>> data;
    Matrix(int n = 0) : data(n, vector<ll>(n, 0)) {}
    Matrix(int n, int m) : data(n, vector<ll>(m, 0)) {}
    ll& at(int i, int j) { return data[i][j]; }
    const ll& at(int i, int j) const { return data[i][j]; }
    int rows() const { return data.size(); }
    int cols() const { return data[0].size(); }

    static Matrix identity(int n) {
        Matrix res(n);
        for (int i = 0; i < n; ++i) res.at(i, i) = 1;
        return res;
    }

    Matrix& operator+=(const Matrix& other) {
        for (int i = 0; i < rows(); ++i)
            for (int j = 0; j < cols(); ++j)
                at(i, j) = (at(i, j) + other.at(i, j)) % MOD;
        return *this;
    }

    Matrix& operator-=(const Matrix& other) {
        for (int i = 0; i < rows(); ++i)
            for (int j = 0; j < cols(); ++j)
                at(i, j) = (at(i, j) - other.at(i, j) + MOD) % MOD;
        return *this;
    }

    Matrix& operator*=(const Matrix& other) {
        int r = rows(), c = other.cols(), k = cols();
        vector<vector<ll>> res(r, vector<ll>(c, 0));
        for (int i = 0; i < r; ++i)
            for (int j = 0; j < c; ++j)
                for (int l = 0; l < k; ++l)
                    res[i][j] = (res[i][j] + at(i, l) * other.at(l, j)) % MOD;
        data.swap(res);
        return *this;
    }

    Matrix& operator^=(ll exp) {
        Matrix base = *this;
        Matrix result = Matrix::identity(rows());
        while (exp > 0) {
            if (exp & 1) result *= base;
            base *= base;
            exp >>= 1;
        }
        data.swap(result.data);
        return *this;
    }

    Matrix operator+(const Matrix& other) const { return Matrix(*this) += other; }
    Matrix operator-(const Matrix& other) const { return Matrix(*this) -= other; }
    Matrix operator*(const Matrix& other) const { return Matrix(*this) *= other; }
    Matrix operator^(ll exp) const { return Matrix(*this) ^= exp; }

    void rotate() {
        int sz = data.size();
        Matrix res(sz);
        for (int i = 0; i < K; ++i) {
            for (int j = 0; j < K; ++j)
                res.at(i, j) = at((i + K - 1) % K, (j + K - 1) % K);
            res.at(i, K) = at((i + K - 1) % K, K);
            res.at(K, i) = at(K, (i + K - 1) % K);
        }
        res.at(K, K) = at(K, K);
        data = move(res.data);
    }
};

Matrix mats[70][35];

ll power(ll base, ll exp) {
    ll result = 1;
    while (exp) {
        if (exp & 1) result *= base;
        base *= base;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> K;
    int log_ = 0;
    ll temp = N;
    while (temp >= K) {
        log_++;
        temp /= K;
    }
    mats[0][0] = Matrix::identity(K + 1);
    for (int i = 1; i <= K; ++i) mats[0][0].at(0, i) = 1;
    for (int i = 1; i < K; ++i) {
        mats[0][i] = mats[0][i - 1];
        mats[0][i].rotate();
    }
    for (int l = 1; l <= log_; ++l) {
        mats[l][0] = mats[l - 1][0];
        for (int i = 1; i < K; ++i)
            mats[l][0] = mats[l - 1][i] * mats[l][0];
        for (int i = 1; i < K; ++i) {
            mats[l][i] = mats[l][i - 1];
            mats[l][i].rotate();
        }
    }
    Matrix result(K + 1, 1);
    result.at(K, 0) = 1;
    int pos = 0;
    while (log_ >= 0) {
        while (true) {
            ll p = power(K, log_);
            if (p <= N) {
                N -= p;
                result = mats[log_][pos] * result;
                pos = (pos + 1) % K;
            } else break;
        }
        log_--;
    }
    ll total = 0;
    for (int i = 0; i <= K; ++i) total = (total + result.at(i, 0)) % MOD;
    cout << total << '\n';
}
